package com.andye.warmod.phalanx;import com.andye.warmod.antiair.*;import com.andye.warmod.entity.IncomingWarheadEntity;import com.andye.warmod.warhead.*;import java.util.*;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.phys.Vec3;
public final class PhalanxTargetService{private PhalanxTargetService(){}public static List<PhalanxTargetSnapshot> snapshot(ServerLevel level){ArrayList<PhalanxTargetSnapshot> out=new ArrayList<>();long now=level.getGameTime();for(IncomingWarheadEntity w:IncomingWarheadRegistry.activeWarheads(level)){double age=Math.max(0,now-w.launchGameTime());Vec3 p=WarheadTrajectory.position(w.startPosition(),w.intendedTarget(),age,w.flightTicks()),v=WarheadTrajectory.velocity(w.startPosition(),w.intendedTarget(),age,w.flightTicks());double remaining=Math.max(0,w.flightTicks()-age);PhalanxTargetKind kind=w.clusterCount()>1?PhalanxTargetKind.CLUSTER_SUBMUNITION:w.radarRootTrackId().equals(w.warheadId())?PhalanxTargetKind.DIRECT_WARHEAD:PhalanxTargetKind.TERMINAL_WARHEAD;out.add(new PhalanxTargetSnapshot(w.warheadId(),w.radarRootTrackId(),kind,Optional.of(w.payloadType()),p,v,w.intendedTarget(),remaining,w.clusterCount()>1?.48:.62));}for(var f:AntiAirFlightControllerManager.fallbackSnapshots(level)){if(f.variant()!=AntiAirMissileVariant.MK_I||!f.active())continue;AntiAirFallbackTrajectory.predictImpact(level,f.currentPosition(),f.currentVelocity(),200).ifPresent(impact->out.add(new PhalanxTargetSnapshot(f.interceptorId(),f.interceptorId(),PhalanxTargetKind.MK_I_FALLBACK,Optional.empty(),f.currentPosition(),f.currentVelocity(),impact,estimateTicks(f.currentPosition(),f.currentVelocity(),impact),.8)));}return List.copyOf(out);}private static double estimateTicks(Vec3 p,Vec3 v,Vec3 impact){return Math.min(200,Math.max(1,p.distanceTo(impact)/Math.max(.1,v.length())));}}
